```typescript
// checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { axe, toHaveNoViolations } from 'jest-axe'
import { Checkout } from './Checkout'

expect.extend(toHaveNoViolations)

describe('Checkout Component', () => {
  const mockSubmitOrder = vi.fn()
  const user = userEvent.setup()

  beforeEach(() => {
    vi.clearAllMocks()
  })

  describe('Happy Path - Complete Checkout Flow', () => {
    it('completes checkout when all forms are valid', async () => {
      render(<Checkout onSubmit={mockSubmitOrder} />)

      // Shipping step
      await user.type(screen.getByRole('textbox', { name: /street address/i }), '123 Main St')
      await user.type(screen.getByRole('textbox', { name: /city/i }), 'New York')
      await user.click(screen.getByRole('button', { name: /continue to payment/i }))

      // Payment step
      await user.type(screen.getByRole('textbox', { name: /card number/i }), '4111111111111111')
      await user.type(screen.getByRole('textbox', { name: /expiration/i }), '12/25')
      await user.click(screen.getByRole('button', { name: /review order/i }))

      // Review and submit
      await user.click(screen.getByRole('button', { name: /place order/i }))

      await waitFor(() => {
        expect(screen.getByRole('heading', { name: /order confirmed/i })).toBeInTheDocument()
      })
    })
  })

  describe('Form Validation', () => {
    it('displays error when submitting empty required fields', async () => {
      render(<Checkout onSubmit={mockSubmitOrder} />)

      await user.click(screen.getByRole('button', { name: /continue to payment/i }))

      expect(screen.getByRole('alert')).toHaveTextContent(/address is required/i)
    })

    it('validates credit card format before proceeding', async () => {
      render(<Checkout onSubmit={mockSubmitOrder} initialStep="payment" />)

      await user.type(screen.getByRole('textbox', { name: /card number/i }), '1234')
      await user.click(screen.getByRole('button', { name: /review order/i }))

      expect(screen.getByRole('alert')).toHaveTextContent(/invalid card number/i)
    })
  })

  describe('Error States', () => {
    it('displays payment failure and allows retry', async () => {
      mockSubmitOrder.mockRejectedValueOnce(new Error('Payment declined'))
      render(<Checkout onSubmit={mockSubmitOrder} initialStep="review" />)

      await user.click(screen.getByRole('button', { name: /place order/i }))

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/payment declined/i)
      })
      expect(screen.getByRole('button', { name: /try again/i })).toBeEnabled()
    })
  })

  describe('Loading States', () => {
    it('disables submit button during order processing', async () => {
      mockSubmitOrder.mockImplementation(() => new Promise(() => {}))
      render(<Checkout onSubmit={mockSubmitOrder} initialStep="review" />)

      await user.click(screen.getByRole('button', { name: /place order/i }))

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled()
    })
  })

  describe('Edge Cases', () => {
    it('redirects to cart when cart is empty', () => {
      render(<Checkout onSubmit={mockSubmitOrder} cartItems={[]} />)

      expect(screen.getByText(/your cart is empty/i)).toBeInTheDocument()
    })
  })

  describe('Accessibility', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout onSubmit={mockSubmitOrder} />)
      const results = await axe(container)

      expect(results).toHaveNoViolations()
    })
  })
})
```

